contracts/Params.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

/// @title Params
/// @notice Every tunable number in the system, changeable only by consortium vote.
///
/// Plan section 7.2. k, N, T, rewards, stake and the rest live here rather than
/// as constants in each contract, so the thesis can run a sensitivity test by
/// sending transactions instead of redeploying.
///
/// Changing a value needs approvals from 3 of the 4 consortium members. That is
/// the on-chain governance the thesis argues for: no single organisation can
/// quietly make fraud cheaper by lowering the stake, or make confirmation
/// easier by lowering k.
contract Params {
    uint8 public constant APPROVALS_REQUIRED = 3;

    mapping(bytes32 => uint256) private _values;
    mapping(bytes32 => bool) private _isSet;

    /// consortium members who may approve changes
    mapping(address => bool) public isConsortium;
    uint8 public consortiumCount;

    /// proposal id => member => approved
    mapping(bytes32 => mapping(address => bool)) public approved;
    /// proposal id => number of approvals so far
    mapping(bytes32 => uint8) public approvalCount;

    event ParamChanged(string name, uint256 oldValue, uint256 newValue);
    event ChangeProposed(bytes32 indexed proposalId, string name, uint256 value, address by);
    event ChangeApproved(bytes32 indexed proposalId, address by, uint8 count);

    error NotConsortium();
    error AlreadyApproved();
    error UnknownParam(string name);

    modifier onlyConsortium() {
        if (!isConsortium[msg.sender]) revert NotConsortium();
        _;
    }

    /// @param members the four validator organisations
    constructor(address[] memory members) {
        for (uint256 i = 0; i < members.length; i++) {
            if (!isConsortium[members[i]]) {
                isConsortium[members[i]] = true;
                consortiumCount++;
            }
        }

        // Starting values from plan section 15. Each is a starting point to be
        // justified from data, not a final answer.
        _set("k_confirm", 3);
        _set("N_rewarded", 5);
        _set("T_reward_window", 24 hours);
        _set("T_pending", 72 hours);
        _set("m_checkback", 3);
        _set("stake", 5);
        _set("registration_bond", 25);
        _set("slash_percent", 100);
        _set("rep_threshold_unlearn", 200);
        _set("match_radius_m", 15);
        _set("checkback_radius_m", 20);
        _set("max_reports_per_hour", 20);
        // reward per position, 1-indexed
        _set("reward_1", 10);
        _set("reward_2", 6);
        _set("reward_3", 4);
        _set("reward_4", 2);
        _set("reward_5", 1);
    }

    function _set(string memory name, uint256 value) private {
        bytes32 key = keccak256(bytes(name));
        uint256 old = _values[key];
        _values[key] = value;
        _isSet[key] = true;
        emit ParamChanged(name, old, value);
    }

    /// @notice Read a parameter. Reverts on an unknown name rather than
    /// returning 0, because a silent zero stake or zero k would disable a
    /// safety rule without anyone noticing.
    function get(string calldata name) external view returns (uint256) {
        bytes32 key = keccak256(bytes(name));
        if (!_isSet[key]) revert UnknownParam(name);
        return _values[key];
    }

    function exists(string calldata name) external view returns (bool) {
        return _isSet[keccak256(bytes(name))];
    }

    /// @notice Reward for a 1-indexed confirmation position, 0 past the table.
    function rewardFor(uint256 position) external view returns (uint256) {
        if (position == 0 || position > 5) return 0;
        bytes32 key = keccak256(
            abi.encodePacked("reward_", bytes1(uint8(48 + position)))
        );
        return _values[key];
    }

    function proposalId(string calldata name, uint256 value)
        public
        pure
        returns (bytes32)
    {
        return keccak256(abi.encode(name, value));
    }

    /// @notice Approve a change. The third approval applies it.
    /// A member cannot approve the same proposal twice, so one organisation
    /// cannot reach the threshold alone.
    function approveParam(string calldata name, uint256 value)
        external
        onlyConsortium
    {
        bytes32 pid = proposalId(name, value);
        if (approved[pid][msg.sender]) revert AlreadyApproved();

        approved[pid][msg.sender] = true;
        uint8 count = approvalCount[pid] + 1;
        approvalCount[pid] = count;

        if (count == 1) emit ChangeProposed(pid, name, value, msg.sender);
        emit ChangeApproved(pid, msg.sender, count);

        if (count >= APPROVALS_REQUIRED) {
            _set(name, value);
            delete approvalCount[pid];
        }
    }

    /// @notice Withdraw an approval before the threshold is reached.
    function revokeApproval(string calldata name, uint256 value)
        external
        onlyConsortium
    {
        bytes32 pid = proposalId(name, value);
        if (!approved[pid][msg.sender]) return;
        approved[pid][msg.sender] = false;
        approvalCount[pid] -= 1;
    }
}

contracts/Registry.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

/// @title Registry
/// @notice Who is a car, who owns it, and who holds a special role.
///
/// Plan section 7.3. Two rules here carry most of the security argument.
///
/// One registration per vehicle registration hash. This is the Sybil defence:
/// confirmation requires k *distinct owners*, so an attacker who could mint
/// identities freely could confirm any fake fault alone. The vehicle document
/// is the scarce thing an attacker cannot copy.
///
/// Owner identity is stored as a hash, never a name or a document. The chain is
/// publicly readable, so putting an owner's identity on it would publish who
/// drives where.
interface IRoadPoint {
    function mintBond(address car, uint256 amount) external;
}

interface IParams {
    function get(string calldata name) external view returns (uint256);
}

contract Registry {
    bytes32 public constant REPAIR = keccak256("REPAIR");
    bytes32 public constant MERCHANT = keccak256("MERCHANT");
    bytes32 public constant FL_SERVER = keccak256("FL_SERVER");
    bytes32 public constant UNLEARN_SERVICE = keccak256("UNLEARN_SERVICE");
    bytes32 public constant KEEPER = keccak256("KEEPER");
    bytes32 public constant AUDITOR = keccak256("AUDITOR");

    struct Car {
        bytes32 ownerId;        // hash of the owner's identity, never the identity
        bytes32 vehicleRegHash; // hash of the vehicle registration document
        bool active;
        bool excludedFromFL;    // set after client unlearning
        uint64 registeredAt;
    }

    address public admin;               // road authority
    IParams public params;
    IRoadPoint public roadPoint;

    mapping(address => Car) private _cars;
    mapping(bytes32 => address) public carByVehicleHash;
    mapping(address => mapping(bytes32 => bool)) private _roles;
    uint256 public carCount;

    event CarRegistered(address indexed car, bytes32 indexed ownerId, uint64 at);
    event CarLeft(address indexed car, bytes32 indexed ownerId, string reason);
    event RoleSet(address indexed who, bytes32 indexed role, bool enabled);
    event FLExclusionSet(address indexed car, bool excluded);
    event AdminChanged(address oldAdmin, address newAdmin);

    error NotAdmin();
    error VehicleAlreadyRegistered(address existingCar);
    error UnknownCar();
    error ZeroAddress();

    modifier onlyAdmin() {
        if (msg.sender != admin) revert NotAdmin();
        _;
    }

    constructor(address admin_, address params_) {
        if (admin_ == address(0) || params_ == address(0)) revert ZeroAddress();
        admin = admin_;
        params = IParams(params_);
    }

    /// Set once after RoadPoint is deployed, since the two reference each other.
    function setRoadPoint(address roadPoint_) external onlyAdmin {
        if (roadPoint_ == address(0)) revert ZeroAddress();
        roadPoint = IRoadPoint(roadPoint_);
    }

    function setAdmin(address newAdmin) external onlyAdmin {
        if (newAdmin == address(0)) revert ZeroAddress();
        emit AdminChanged(admin, newAdmin);
        admin = newAdmin;
    }

    /// @notice Register a car and mint its locked registration bond.
    /// @param vehicleRegHash keccak256 of the vehicle registration document.
    /// Reverts if that document is already registered, which is what stops one
    /// attacker from becoming k distinct owners.
    function registerCar(address car, bytes32 ownerId, bytes32 vehicleRegHash)
        external
        onlyAdmin
    {
        if (car == address(0)) revert ZeroAddress();
        address existing = carByVehicleHash[vehicleRegHash];
        if (existing != address(0)) revert VehicleAlreadyRegistered(existing);

        _cars[car] = Car({
            ownerId: ownerId,
            vehicleRegHash: vehicleRegHash,
            active: true,
            excludedFromFL: false,
            registeredAt: uint64(block.timestamp)
        });
        carByVehicleHash[vehicleRegHash] = car;
        carCount++;

        emit CarRegistered(car, ownerId, uint64(block.timestamp));

        if (address(roadPoint) != address(0)) {
            roadPoint.mintBond(car, params.get("registration_bond"));
        }
    }

    /// @notice Retire a car. Emits CarLeft, which the unlearning service treats
    /// as a request to remove that car's contribution from the global model.
    function deregisterCar(address car, string calldata reason) external {
        Car storage c = _cars[car];
        if (c.registeredAt == 0) revert UnknownCar();
        if (msg.sender != admin && msg.sender != car) revert NotAdmin();

        c.active = false;
        // The vehicle hash stays claimed: freeing it would let an owner
        // deregister and re-register to shed a bad reputation.
        emit CarLeft(car, c.ownerId, reason);
    }

    function setRole(address who, bytes32 role, bool enabled) external onlyAdmin {
        if (who == address(0)) revert ZeroAddress();
        _roles[who][role] = enabled;
        emit RoleSet(who, role, enabled);
    }

    /// Called by the unlearning service once a car's influence is removed, so
    /// the FL server skips its future updates.
    function setFLExclusion(address car, bool excluded) external {
        if (msg.sender != admin && !_roles[msg.sender][UNLEARN_SERVICE]) {
            revert NotAdmin();
        }
        if (_cars[car].registeredAt == 0) revert UnknownCar();
        _cars[car].excludedFromFL = excluded;
        emit FLExclusionSet(car, excluded);
    }

    // ------------------------------------------------------------------ views

    function ownerOf(address car) external view returns (bytes32) {
        return _cars[car].ownerId;
    }

    function isActive(address car) external view returns (bool) {
        return _cars[car].active;
    }

    function isRegistered(address car) external view returns (bool) {
        return _cars[car].registeredAt != 0;
    }

    function isExcludedFromFL(address car) external view returns (bool) {
        return _cars[car].excludedFromFL;
    }

    function hasRole(address who, bytes32 role) external view returns (bool) {
        return _roles[who][role];
    }

    function carInfo(address car) external view returns (Car memory) {
        return _cars[car];
    }

    /// @notice Do these two cars share an owner? The distinct-owner rule in
    /// FaultLifecycle calls this, and it is what blocks the collusion attack
    /// where one person runs three cars.
    function sameOwner(address a, address b) external view returns (bool) {
        bytes32 oa = _cars[a].ownerId;
        return oa != bytes32(0) && oa == _cars[b].ownerId;
    }
}

contracts/RoadPoint.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import {ERC20} from "@openzeppelin/contracts/token/ERC20/ERC20.sol";
import {ECDSA} from "@openzeppelin/contracts/utils/cryptography/ECDSA.sol";
import {MessageHashUtils} from "@openzeppelin/contracts/utils/cryptography/MessageHashUtils.sol";

/// @title RoadPoint
/// @notice A reward point that is deliberately not a cryptocurrency.
///
/// Plan section 7.4. Cryptocurrency trading is illegal in Bangladesh, so this
/// token must never behave like one. Every path that would make it tradable is
/// closed: transfer and transferFrom revert, approve reverts, and the only way
/// out is redemption at a registered toll or fuel merchant, which burns the
/// points. There is no market, no exchange rate on-chain, and no way to move
/// value between two cars.
///
/// It keeps the ERC-20 interface only so that balances and events are readable
/// by standard tooling.
///
/// Balances are split in two. Bond is the locked amount minted at registration:
/// it backs stakes and can never be redeemed, so it is not a reward and cannot
/// be cashed out. Earned points are what a car actually gets to spend.
interface IRegistryView {
    function isActive(address car) external view returns (bool);
    function hasRole(address who, bytes32 role) external view returns (bool);
}

contract RoadPoint is ERC20 {
    using ECDSA for bytes32;

    bytes32 public constant MERCHANT = keccak256("MERCHANT");

    address public admin;
    IRegistryView public registry;

    /// contracts allowed to mint, lock, slash — set to FaultLifecycle
    mapping(address => bool) public isController;

    /// locked registration bond, never redeemable
    mapping(address => uint256) public bondOf;
    /// amount currently locked as stake on open reports
    mapping(address => uint256) public lockedOf;
    /// owed back after a clawback found the balance too small
    mapping(address => uint256) public debtOf;
    /// replay protection for redemptions
    mapping(address => uint256) public nonceOf;

    event ControllerSet(address indexed who, bool enabled);
    event BondMinted(address indexed car, uint256 amount);
    event Locked(address indexed car, uint256 amount);
    event Unlocked(address indexed car, uint256 amount);
    event Slashed(address indexed car, uint256 amount);
    event Redeemed(address indexed car, bytes32 indexed merchantId, uint256 amount);
    event ClawedBack(address indexed car, uint256 burned, uint256 debtAdded);
    event DebtRepaid(address indexed car, uint256 amount, uint256 remaining);

    error NotAdmin();
    error NotController();
    error NotMerchant();
    error TransfersDisabled();
    error ApprovalsDisabled();
    error InsufficientFree(uint256 free, uint256 needed);
    error InsufficientLocked(uint256 locked, uint256 needed);
    error BondNotRedeemable();
    error BadSignature();
    error CarNotActive();

    modifier onlyAdmin() {
        if (msg.sender != admin) revert NotAdmin();
        _;
    }
    modifier onlyController() {
        if (!isController[msg.sender]) revert NotController();
        _;
    }

    constructor(address admin_, address registry_) ERC20("RoadPoint", "RP") {
        admin = admin_;
        registry = IRegistryView(registry_);
    }

    function setController(address who, bool enabled) external onlyAdmin {
        isController[who] = enabled;
        emit ControllerSet(who, enabled);
    }

    function setRegistry(address registry_) external onlyAdmin {
        registry = IRegistryView(registry_);
    }

    // ----------------------------------------------- the non-transferable part

    /// Car-to-car transfer is the thing that would make this a currency.
    function transfer(address, uint256) public pure override returns (bool) {
        revert TransfersDisabled();
    }

    function transferFrom(address, address, uint256) public pure override returns (bool) {
        revert TransfersDisabled();
    }

    /// Approvals exist only to enable transferFrom, so they are closed too.
    function approve(address, uint256) public pure override returns (bool) {
        revert ApprovalsDisabled();
    }

    // -------------------------------------------------------------- accounting

    /// Points a car may actually spend: balance minus bond minus locked stake.
    function freeBalance(address car) public view returns (uint256) {
        uint256 bal = balanceOf(car);
        uint256 reserved = bondOf[car] + lockedOf[car];
        return bal > reserved ? bal - reserved : 0;
    }

    /// Bond plus earned points that are not currently staked.
    function stakeable(address car) public view returns (uint256) {
        uint256 bal = balanceOf(car);
        return bal > lockedOf[car] ? bal - lockedOf[car] : 0;
    }

    function mintBond(address car, uint256 amount) external {
        if (msg.sender != admin && !isController[msg.sender]
            && msg.sender != address(registry)) revert NotController();
        bondOf[car] += amount;
        _mint(car, amount);
        emit BondMinted(car, amount);
    }

    /// Reward for a confirmed report. Any outstanding debt is paid first, so a
    /// car proven fraudulent cannot simply keep earning past its clawback.
    function mint(address car, uint256 amount) external onlyController {
        uint256 debt = debtOf[car];
        if (debt > 0) {
            uint256 pay = debt < amount ? debt : amount;
            debtOf[car] = debt - pay;
            amount -= pay;
            emit DebtRepaid(car, pay, debtOf[car]);
        }
        if (amount > 0) _mint(car, amount);
    }

    function lock(address car, uint256 amount) external onlyController {
        uint256 free = stakeable(car);
        if (free < amount) revert InsufficientFree(free, amount);
        lockedOf[car] += amount;
        emit Locked(car, amount);
    }

    function unlock(address car, uint256 amount) external onlyController {
        uint256 locked = lockedOf[car];
        if (locked < amount) revert InsufficientLocked(locked, amount);
        lockedOf[car] = locked - amount;
        emit Unlocked(car, amount);
    }

    /// Burn a locked stake after a fault is rejected. Burns bond first, because
    /// the bond is what the stake was drawn against.
    function slash(address car, uint256 amount) external onlyController {
        uint256 locked = lockedOf[car];
        if (locked < amount) revert InsufficientLocked(locked, amount);
        lockedOf[car] = locked - amount;

        uint256 bond = bondOf[car];
        uint256 fromBond = bond < amount ? bond : amount;
        bondOf[car] = bond - fromBond;

        _burn(car, amount);
        emit Slashed(car, amount);
    }

    /// Remove rewards already paid for a fault later proven fake. If the car
    /// has spent them, the shortfall becomes a debt that future rewards repay.
    function clawback(address car, uint256 amount) external onlyController {
        uint256 free = freeBalance(car);
        uint256 burn = free < amount ? free : amount;
        uint256 debt = amount - burn;
        if (burn > 0) _burn(car, burn);
        if (debt > 0) debtOf[car] += debt;
        emit ClawedBack(car, burn, debt);
    }

    // -------------------------------------------------------------- redemption

    /// Message the car signs to authorise a redemption at a merchant.
    function redeemDigest(address car, uint256 amount, bytes32 merchantId, uint256 nonce)
        public
        view
        returns (bytes32)
    {
        return MessageHashUtils.toEthSignedMessageHash(
            keccak256(abi.encode(block.chainid, address(this), car, amount, merchantId, nonce))
        );
    }

    /// @notice Burn points in exchange for toll or fuel. Called by the merchant
    /// with a signature from the car, so the car must consent and the merchant
    /// cannot drain a balance on its own.
    ///
    /// The nonce is what stops the double-redeem attack: a replayed signature
    /// carries a stale nonce and reverts. With QBFT finality the merchant can
    /// accept as soon as the transaction is mined.
    function redeem(
        address car,
        uint256 amount,
        bytes32 merchantId,
        bytes calldata signature
    ) external {
        if (!registry.hasRole(msg.sender, MERCHANT)) revert NotMerchant();
        if (!registry.isActive(car)) revert CarNotActive();

        uint256 free = freeBalance(car);
        if (free < amount) revert InsufficientFree(free, amount);

        uint256 nonce = nonceOf[car];
        bytes32 digest = redeemDigest(car, amount, merchantId, nonce);
        if (digest.recover(signature) != car) revert BadSignature();

        nonceOf[car] = nonce + 1;
        _burn(car, amount);
        emit Redeemed(car, merchantId, amount);
    }

    /// Explicit rather than implicit: bond can never leave as value.
    function redeemBond(address, uint256) external pure {
        revert BondNotRedeemable();
    }
}

